-- ============================================================
-- 0078_rondas_sociales.sql
-- GENERADO por scripts/build-rondas.mjs — no editar a mano.
--
-- Ciencias Sociales y Competencias Ciudadanas: módulos 4 (primera ronda) y 6
-- (ronda final) pasan a ser rondas de preguntas del banco (igual que 0075 en
-- las otras asignaturas, ver §14 de CLAUDE.md). 49 preguntas en el banco, con
-- DIFICULTAD REAL del documento del equipo académico:
--   primera ronda: 10 preguntas de dificultad baja y media
--   ronda final:   10 preguntas de dificultad alta
-- Recorre la familia COMPLETA del curso (base, copias por colegio y copias de
-- copias). Solo convierte módulos que siguen "Pendiente" (o con el banco viejo
-- en texto); lo editado a mano se respeta y se informa.
-- Requiere 0075 (snapshot con texto de lectura y pista). Idempotente.
-- EJECUTAR en Supabase SQL Editor.
-- ============================================================

drop table if exists _0078_estado;
create temp table _0078_estado (estado text, curso text, detalle text);

do $$
declare
  v_base uuid := (select coalesce(parent_course_id, id) from public.courses where id = '9e6ddb8b-bcf1-42c0-926b-cc8037cb70b3'::uuid);
  v_r1 jsonb := $soc1${"bank":"sociales","bankRound":1,"passingScore":0,"questions":[{"id":"soc-01","question":"Como argumento a favor del vegetarianismo, una persona afirma que consumir carne es nocivo para los humanos porque el animal, del cual se obtiene esta, sufre en el proceso, y esto produce energías negativas que se transmiten al consumidor y perjudican su salud. Otra persona, igualmente a favor del vegetarianismo, sostiene que el consumo de productos de origen animal es un acto amoral, en la medida en que resulta del abuso e insensibilidad del ser humano ante los demás seres vivos.\n¿Cuál de las siguientes afirmaciones sobre la relación entre las opiniones presentadas NO es correcta?","options":["Son similares, porque ambas van en contra del consumo de carne.","Son complementarias, porque ambas promueven el vegetarianismo cuando argumentan la obligación de proteger a los animales.","Son diferentes, porque la primera aboga por la salud del ser humano y la segunda, por el bienestar de los animales.","Son disímiles, porque la primera se centra en cómo el animal afecta al ser humano y la segunda, en cómo el ser humano afecta el animal."],"correct":1,"hint":"Fíjate en el NO: busca la afirmación que describe MAL lo que defiende cada persona.","difficulty":"media","timeLimit":120,"explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Comprende perspectivas de distintos actores y grupos sociales."},{"id":"soc-03","question":"Un padre de familia no está de acuerdo con la participación de profesores homosexuales en la educación de sus hijos. Al respecto, el rector del colegio argumenta: “Las personas con inclinaciones homosexuales, como todas las personas, merecen ser amadas. Además, en muchos países gran parte de la población masculina y femenina es homosexual, y las preferencias sexuales son el resultado de una compleja interacción de la biología con el medio ambiente. Yo creo que los homosexuales pueden enseñar, siempre y cuando controlen su comportamiento en clase y no afecten la orientación sexual de los estudiantes”.\n¿Cuál de los siguientes enunciados del rector contiene un prejuicio cuestionable?","options":["En muchos países, gran parte de la población masculina y femenina es homosexual.","Las personas con inclinaciones homosexuales, como todas las personas, merecen ser amadas.","Las preferencias sexuales son el resultado de una compleja interacción de la biología con el medio ambiente.","Los homosexuales pueden enseñar, siempre y cuando controlen su comportamiento en clase y no afecte la orientación sexual de los estudiantes."],"correct":3,"hint":"Un prejuicio da por hecho algo sin fundamento sobre un grupo. ¿Qué frase supone que se “contagia” una orientación?","difficulty":"media","timeLimit":120,"explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Contextualiza y evalúa usos de fuentes y argumentos."},{"id":"soc-05","question":"En Colombia se debate sobre la posibilidad de legalizar el tráfico y consumo de drogas, para contrarrestar los efectos económicos y sociales del narcotráfico. Algunos sectores sociales plantean que esta alternativa es indeseable y proponen, en cambio, fortalecer los procesos de sensibilización entre los consumidores sobre los riesgos de salud asociados al consumo de drogas. En contraste, otros sectores sociales proponen endurecer las penas para los productores y expendedores de drogas, así como para aquellos consumidores que porten más de la dosis legalmente permitida.\nLas dos posiciones frente a la legalización de las drogas descritas en el texto son","options":["diferentes, porque una está a favor de la legalización y la otra a favor del endurecimiento de las sanciones legales.","similares, porque ambas consideran que la regulación legal del consumo tiene un efecto directo sobre el narcotráfico.","diferentes, porque una plantea que la lucha contra el narcotráfico debe ser por la vía de la represión y la otra por la vía de la prevención del consumo.","similares, porque ambas están en contra de la legalización y se enfocan en la protección de los consumidores de drogas."],"correct":2,"hint":"Lee con calma las DOS posturas: ¿alguna de ellas está a favor de legalizar?","difficulty":"media","timeLimit":120,"explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Comprende perspectivas de distintos actores y grupos sociales."},{"id":"soc-06","question":"La asamblea de propietarios de un edificio de la ciudad estudia la posibilidad de ampliar el horario para las reuniones privadas que se realizan en el salón comunal. Los propietarios de los pisos altos están de acuerdo en que se amplíe el horario hasta la 1:00 a. m. y mencionan que es la hora ideal para finalizar las reuniones; los propietarios del primer piso (lugar donde se encuentra el salón comunal) están en desacuerdo con el horario, ya que son ellos quienes se afectan por el ruido ocasionado por este tipo de reuniones a avanzadas horas de la noche. Después de que los propietarios exponen sus intereses, se realiza una votación y se decide que se ampliará el uso del salón hasta la medianoche. ¿Esta solución se ajusta a los intereses de todos los vecinos?","options":["No, porque los habitantes de los pisos más altos no pueden aprovechar las fiestas que se hagan en el salón comunal.","Sí, porque debido a que la propuesta se aprobó, todos los vecinos están llamados a tener los mismos intereses.","No, porque el ruido de las fiestas afecta más a los propietarios del primer piso cercanos al salón comunal.","Sí, porque todos los propietarios tuvieron derecho a exponer sus ideas y a votar según sus intereses."],"correct":2,"hint":"Que se vote no significa que todos queden bien: ¿quién sigue afectado por el ruido?","difficulty":"facil","timeLimit":135,"explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Comprende perspectivas de distintos actores y grupos sociales."},{"id":"soc-07","question":"Se ha generado un conflicto entre una empresa constructora y unas organizaciones ambientalistas en torno al desarrollo de un proyecto de apartamentos sobre un humedal. Por un lado, los ambientalistas afirman que cualquier construcción pone en riesgo todo el ecosistema del humedal. La constructora, por su parte, argumenta que el humedal no se afectará y que, por el contrario, el proyecto busca integrar el medio ambiente a sus zonas comunes.\nPara resolver el conflicto entre la constructora y los ambientalistas, se plantea que la constructora modifique sus planos para reducir el impacto sobre el humedal y salvar así algunos animales y árboles.\n¿Cómo se ajusta esta solución a los intereses de la constructora y de los ambientalistas?","options":["La solución beneficia a ambas partes, pues busca reducir gradualmente el daño ambiental y garantizar el negocio de la constructora.","La solución beneficia solamente a una de las partes en detrimento del medio ambiente y del ecosistema de humedal.","La solución beneficia a los ambientalistas, pues defiende sus intereses y perjudica el negocio de la constructora.","La solución no beneficia a ninguna de las partes, porque el humedal será destruido y la constructora no podrá realizar su proyecto de construcción de apartamentos."],"correct":1,"hint":"Pregúntate quién gana de verdad: la constructora sigue construyendo… ¿y el humedal?","difficulty":"media","timeLimit":135,"explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Comprende perspectivas de distintos actores y grupos sociales."},{"id":"soc-09","question":"La Constitución política de Colombia se puede modificar mediante","options":["una consulta popular.","un plebiscito.","un referendo.","un cabildo abierto."],"correct":2,"hint":"De los mecanismos de participación, solo uno permite aprobar reformas a la Constitución por voto popular.","difficulty":"media","timeLimit":60,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-11","question":"Un presidente de Colombia está finalizando su periodo presidencial y, debido a la alta popularidad de la que goza, decide proponer la inclusión de la reelección presidencial indefinida dentro de la Constitución. Para tal fin, quiere convocar un referendo.\n¿El presidente puede hacer esto?","options":["Sí, porque los referendos permiten reformar la Constitución.","No, porque la Constitución no puede reformarla el Ejecutivo; solo a través de una Asamblea Constituyente.","Sí, porque el presidente puede modificar la Constitución por su cuenta, sin acudir al poder legislativo.","No, porque los referendos no permiten reformar la Constitución."],"correct":0,"hint":"¿Cuál de los mecanismos de participación permite reformar la Constitución?","difficulty":"media","timeLimit":75,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-12","question":"El alcalde de un municipio, su abogado asesor y el que es considerado el mayor contratista de la región compraron, por $244 millones, 129.881 m2 de tierra en dos veredas de ese municipio. Gracias a unos $4.700 millones de recursos nacionales y municipales que el mandatario destinó a rieles, pavimentos e iluminación de vías, el precio de ese pedazo de tierra comprado puede superar hoy los $12.000 millones.\nLa situación ha sido conocida por diferentes personas quienes denunciaron que, después de comprar esas propiedades, el alcalde incluyó dentro del Plan Básico de Ordenamiento Territorial (PBOT) del municipio, inversiones en vías e iluminación que no estaban en el Plan de Desarrollo que fue presentado al inicio del mandato, pero que sí favorecían la valorización de esos predios rurales.\nConsultado sobre esa denuncia, el alcalde reconoció que los beneficios no son solo para él y sus allegados, sino para toda la comunidad.\nTomado y adaptado de: www.elcolombiano.com.\nDe acuerdo con el texto anterior, los señalamientos en contra del alcalde obedecen a que los denunciantes","options":["no obtuvieron beneficio de las obras desarrolladas en el PBOT.","creen que el alcalde no ha hecho obras que beneficien al municipio.","tienen evidencias para afirmar que el alcalde abusó de su poder.","no quieren que el alcalde invierta en las zonas rurales del municipio."],"correct":2,"hint":"Los denunciantes señalan que el alcalde compró tierras y luego las valorizó con obras públicas.","difficulty":"media","timeLimit":135,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-13","question":"El estado de excepción es una medida temporal consignada en la Constitución política de Colombia, a la que el presidente puede acudir cuando algún hecho amenaza la estabilidad del Estado. En caso de grave perturbación del orden público, el presidente tendrá la facultad de, por ejemplo, restringir la celebración de reuniones y manifestaciones públicas; ordenar la aprehensión preventiva de personas; modificar el presupuesto; aumentar y reducir penas; modificar el procedimiento penal y decretar leyes para atender el problema, las cuales serán evaluadas por la Corte Constitucional.\nA partir de la anterior definición, se puede afirmar que durante el estado de excepción en Colombia se alteraría la distribución del poder público, porque","options":["no es posible modificar el presupuesto del país, porque los recursos públicos se adjudican previamente.","la Rama Ejecutiva debe ser la única encargada de restringir las manifestaciones públicas y los desórdenes causados por estas.","la Rama Judicial debe ser la única encargada de ordenar el arresto de personas por medio de una orden judicial.","el presidente podría proponer leyes cuando, de manera ordinaria, la Rama Legislativa es la única que puede hacer esto."],"correct":2,"hint":"En condiciones normales, ¿qué rama del poder es la que ordena la captura de una persona?","difficulty":"media","timeLimit":135,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-16","question":"Las siguientes son dos caricaturas publicadas en la prensa colombiana.\n¿Qué periodo de la historia política colombiana se representa en estas caricaturas?","options":["La Violencia política.","El Frente Nacional.","La Patria Boba.","El gobierno de Rojas Pinilla."],"correct":0,"hint":"Lee los rótulos de las caricaturas: “violencia conservadora”, “víctimas liberales”, “violencia liberal”…","difficulty":"media","timeLimit":60,"image":"/preguntas/sociales/caricaturas-la-violencia.jpg","explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Contextualiza y evalúa usos de fuentes y argumentos."}]}$soc1$::jsonb;
  v_r2 jsonb := $soc2${"bank":"sociales","bankRound":2,"passingScore":0,"questions":[{"id":"soc-02","question":"Los habitantes de un barrio de clase media se oponen a que se construyan, en este, viviendas de interés social. Afirman que las personas de escasos recursos económicos que se beneficiarían con estas viviendas representarían un peligro para la seguridad de los habitantes actuales del barrio.\nSeñalan que las zonas más pobres de la ciudad son también las más inseguras, y argumentan que esto prueba que una persona de escasos recursos tiene una probabilidad más alta de ser un delincuente que una persona acomodada.\nDe los siguientes enunciados, ¿cuál contiene un argumento válido en contra de las afirmaciones de los habitantes del barrio de clase media?","options":["Quienes ejercen la delincuencia en una zona pobre de la ciudad pueden no ser habitantes de esa zona.","Entre los delincuentes nunca hay personas de escasos recursos, pues todos son adinerados precisamente gracias a sus actividades delictivas.","Los delincuentes que habitan en las zonas más pobres de la ciudad dejarían de violar la ley, si contaran con mejores condiciones de vida.","Hay casos en que la pobreza y la falta de oportunidades llevan a una persona, en un momento de desesperación, a cometer un delito."],"correct":0,"hint":"Un argumento válido ataca el razonamiento: ¿que una zona sea insegura prueba quién comete allí los delitos?","difficulty":"dificil","timeLimit":120,"explanation":"Competencia: Interpretación y análisis de perspectivas. Afirmación: Contextualiza y evalúa usos de fuentes y argumentos."},{"id":"soc-04","question":"Los siguientes magnicidios tuvieron incidencia en la historia política de Colombia durante el siglo XX:\n1. Asesinato de Luis Carlos Galán.\n2. Asesinato de Jorge Eliécer Gaitán.\n3. Asesinato de Rafael Uribe Uribe.\n4. Asesinato de Álvaro Gómez Hurtado.\nEl orden cronológico de ocurrencia de estos hechos es","options":["2, 3, 1 y 4","3, 2, 1 y 4.","3, 1, 2 y 4.","4, 3, 2 y 4."],"correct":1,"hint":"Ubica cada magnicidio en su década: Uribe Uribe a inicios de siglo, Gaitán en 1948, Galán en 1989…","difficulty":"dificil","timeLimit":60,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende dimensiones espaciales y temporales de eventos, problemáticas y prácticas sociales."},{"id":"soc-08","question":"Un estudio realizado por la Organización de las Naciones Unidas (ONU) sostiene que América Latina es la región más urbanizada del mundo. Aunque esto aumenta las oportunidades laborales y mejora las condiciones de vida de muchas personas, su costo económico, social y ambiental es demasiado alto, ya que han proliferado –y seguirán aumentando– barrios pobres y desiguales que expanden el casco urbano e invaden zonas rurales. Para atender este problema, el estudio plantea tres propuestas. La primera es densificar las ciudades; así, en lugar de expandirse hacia zonas rurales, donde se producen los alimentos, se aumenta la vivienda vertical (edificios). La segunda solución es acelerar las reformas urbanas para legalizar los barrios de invasión, ofreciéndoles a quienes habitan allí acceso a servicios públicos y títulos de propiedad. La tercera alternativa es aumentar la oferta de transporte público, lo cual ayudaría a facilitar la movilidad desde la periferia hacia los centros urbanos.\nTomado de: Redacción BBC Mundo, “América Latina más urbanizada y más desigual”, en BBC Mundo, agosto de 2012.\n¿Qué tipo de relación se puede establecer entre las propuestas de solución al problema de la urbanización en América Latina?","options":["Complementariedad, pues todas las soluciones priorizan el desarrollo económico de los centros urbanos.","Compatibilidad, pues todas las soluciones se enfocan hacia la recuperación de las zonas de producción rural.","Complementariedad, pues todas las soluciones se enfocan hacia la mitigación de los costos sociales y económicos de la expansión urbana.","Compatibilidad, pues todas las soluciones priorizan el mejoramiento de la calidad de vida de los habitantes provenientes de zonas rurales."],"correct":2,"hint":"Las tres propuestas atacan el mismo problema: ¿cuál es el costo de la expansión urbana?","difficulty":"dificil","timeLimit":150,"explanation":"Competencia: Pensamiento reflexivo y sistémico. Afirmación: Comprende que los problemas y sus soluciones involucran distintas dimensiones y reconoce relaciones entre estas."},{"id":"soc-10","question":"Un ciudadano se encontraba inconforme con el actual sistema de salud en Colombia y quería promover una reforma a la Ley 100 de 1993 (Ley de Seguridad Social) para introducir mejoras en esta materia. Para ello, presentó una propuesta ante el Congreso de la República a través de una “iniciativa popular”, a fin de modificar varios artículos de la mencionada ley.\nEl procedimiento realizado por el ciudadano es","options":["inviable, porque la Constitución política de Colombia establece que un ciudadano no tiene la facultad por sí solo para introducir propuestas de reforma a las leyes colombianas.","viable, porque la Constitución política de Colombia establece que se requiere un ciudadano para proponer una iniciativa popular que reforme una ley.","inviable, porque la Constitución política de Colombia establece que se requiere el 5 % del censo electoral para presentar una iniciativa popular que reforme una ley.","viable, porque la Constitución política de Colombia establece que se requiere el 5 % del apoyo de los congresistas para que la iniciativa popular se apruebe."],"correct":2,"hint":"La iniciativa popular necesita un respaldo mínimo de firmas del censo electoral, no de una sola persona.","difficulty":"dificil","timeLimit":120,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-14","question":"En Colombia, las ramas del poder público pueden ejercer control político entre sí para garantizar el equilibrio de poderes y evitar abusos. Una de estas ramas cuenta con dos mecanismos: la citación a un debate de control político y la moción de censura.\nLa citación a un debate de control político permite indagar sobre las acciones u omisiones de los funcionarios del Estado, así como obtener información relevante de su gestión y del cumplimiento de sus labores. Por otro lado, la moción de censura es un mecanismo a través del cual se reprocha la actuación de uno o varios ministros, dando lugar a la separación de su cargo.\nTomado y adaptado de: www.congresovisible.org.\nDe acuerdo con la Constitución política de Colombia, ¿cuál de las ramas del poder puede ejercer control político a través de citaciones y mociones de censura?","options":["La Rama Electoral.","La Rama Ejecutiva.","La Rama Judicial.","La Rama Legislativa."],"correct":3,"hint":"¿Qué rama cita a los ministros a debate y puede separarlos del cargo con una moción de censura?","difficulty":"dificil","timeLimit":105,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-15","question":"En la Constitución política de Colombia se establece que los derechos de los menores de edad están por encima de los de otros particulares. Por lo anterior, si un menor de catorce años de edad comete un delito no puede ser enviado a prisión y debe ser juzgado según un código penal diferente del ordinario. Un presidente de turno considera que, debido a este trato especial que se da en el juzgamiento de los menores, la delincuencia juvenil ha ido incrementándose; por ello, decide convocar a la ciudadanía para conocer si esta apoyaría que se anule la norma constitucional que pone los derechos de los menores por encima de los del resto de la población.\nDe acuerdo con los mecanismos de participación directa que contempla la Constitución, ¿cuál de los siguientes es el adecuado para que el presidente pueda adelantar su iniciativa?","options":["El plebiscito.","El referendo.","La consulta popular.","El cabildo abierto."],"correct":1,"hint":"Se trata de anular una norma de la Constitución: ¿qué mecanismo permite derogar normas por voto popular?","difficulty":"dificil","timeLimit":105,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."},{"id":"soc-20","question":"Considere el siguiente fragmento extraído de un Plan nacional de desarrollo de México: “La productividad no sólo se incrementa con las grandes reformas estructurales. El proceso de crecimiento del país también se puede y debe impulsar desde los sectores privado, social y desde todos los órdenes de gobierno. En este sentido, esta estrategia plantea que la Administración Pública Federal busque el incremento de la productividad mediante la eliminación de trabas que impiden el funcionamiento adecuado de la economía, promoviendo la creación de empleos, mejorando la regulación y, de manera especial, simplificando la normatividad y trámites gubernamentales”.\nTomado de: Plan nacional de desarrollo 2013- 2018, gobierno de los Estados Unidos de México, p. 23. Disponible en: http://www.snieg.mx/contenidos/espanol/normatividad/MarcoJuridico/PND_2013-2018.pdf\n¿Con cuál de los siguientes modelos es afín esta propuesta para mejorar la productividad económica?","options":["Con el socialismo, porque busca que el Estado tenga un control total de la economía.","Con la monarquía, porque centraliza las decisiones económicas en el jefe de Estado.","Con el neoliberalismo, porque restringe el rol del Estado a la protección del mercado.","Con la democracia, porque invita a todos a tomar parte en las decisiones económicas."],"correct":2,"hint":"Eliminar trabas y simplificar trámites para que funcione el mercado: ¿qué modelo propone eso?","difficulty":"dificil","timeLimit":135,"explanation":"Competencia: Pensamiento reflexivo y sistémico. Afirmación: Evalúa usos sociales de las ciencias sociales."},{"id":"soc-22","question":"Lea detenidamente la siguiente definición de proteccionismo económico: “Se puede definir el proteccionismo como el uso de varios mecanismos con el objetivo principal de proteger a las empresas nacionales de la competencia extranjera. El mecanismo más utilizado es el de aplicar un alto nivel de impuestos a la entrada de productos hechos en otros países (estos impuestos se denominan aranceles). (...) Los aranceles son una barrera ya que son costos que tienen que pagar las empresas al comerciar entre países. Estos costos aumentan el precio del producto y, por lo tanto, dificultan su venta”.\nTomado de: http://www.banrepcultural.org/blaavirtual/ayudadetareas/economia/econo89.htm\nTeniendo en cuenta el fragmento anterior, ¿en cuál de las siguientes condiciones se justificaría el uso del modelo proteccionista en un país?","options":["Cuando se fabrica tecnología de punta para optimizar la producción de alimentos.","Cuando tiene suelos desérticos que impiden la producción de alimentos.","Cuando importa un buen número de alimentos que se producen en su territorio.","Cuando exporta más alimentos de los que compra en los mercados extranjeros."],"correct":2,"hint":"Los aranceles protegen lo que el país ya produce. ¿Cuándo tiene sentido protegerlo?","difficulty":"dificil","timeLimit":120,"explanation":"Competencia: Pensamiento reflexivo y sistémico. Afirmación: Evalúa usos sociales de las ciencias sociales."},{"id":"soc-24","question":"Las revoluciones sociales son transformaciones rápidas y fundamentales de la situación de una sociedad y de sus estructuras de clase; se acompañan de las revueltas y se basan en dos coincidencias: cambio estructural por levantamiento de clases y posibilidad de transformación política y social. Entre las revoluciones más sobresalientes están: la Revolución mexicana, la Revolución cubana, la Revolución nicaragüense (sandinista) y la Revolución rusa.\nEl orden cronológico (más antiguo al más reciente) de las revoluciones enunciadas es","options":["Revolución nicaragüense, Revolución rusa, Revolución mexicana, Revolución cubana.","Revolución mexicana, Revolución rusa, Revolución cubana, Revolución nicaragüense.","Revolución rusa, Revolución cubana, Revolución mexicana, Revolución nicaragüense.","Revolución cubana, Revolución mexicana, Revolución nicaragüense."],"correct":1,"hint":"Ubica cada revolución en el tiempo: México 1910, Rusia 1917, Cuba 1959, Nicaragua 1979.","difficulty":"dificil","timeLimit":105,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende dimensiones espaciales y temporales de eventos, problemáticas y prácticas sociales."},{"id":"soc-27","question":"En las principales ciudades del mundo moderno está produciéndose un paulatino abandono de las zonas residenciales del centro urbano, al tiempo que las zonas periféricas tienden a un mayor poblamiento. Estas migraciones las realizan personas o familias que tienen ingresos medios y altos. La principal causa de este fenómeno se atribuye","options":["al creciente desarrollo de la industria en el centro de las ciudades.","a la búsqueda de mejor calidad de vida en barrios tranquilos.","a la escasa oferta de servicios en los barrios del centro de la ciudad.","a la creciente oferta de vivienda barata en las afueras de la ciudad."],"correct":1,"hint":"Quienes se van tienen ingresos medios y altos: no buscan vivienda barata, buscan…","difficulty":"dificil","timeLimit":75,"explanation":"Competencia: Pensamiento social. Afirmación: Comprende modelos conceptuales, sus características y contextos de aplicación."}]}$soc2$::jsonb;
  c record; m record; v_ronda int; v_cd jsonb; v_nombre text;
begin
  if v_base is null then
    insert into _0078_estado values ('CURSO NO ENCONTRADO', '—', 'No existe el curso de Ciencias Sociales en esta base de datos.');
    return;
  end if;

  for c in
    with recursive fam as (
      select id from public.courses where id = v_base
      union
      select ch.id from public.courses ch join fam on ch.parent_course_id = fam.id
    )
    select co.id, co.name, co.draft_modules is not null as has_draft
      from public.courses co join fam on fam.id = co.id
     order by co.parent_course_id nulls first, co.name
  loop
    if c.has_draft then
      insert into _0078_estado values ('BORRADOR PENDIENTE', c.name,
        'Tiene un borrador sin publicar en el editor de ruta: descartarlo antes de publicar, o volverán los módulos 4 y 6 anteriores.');
    end if;
    foreach v_ronda in array array[4, 6] loop
      v_cd := case when v_ronda = 4 then v_r1 else v_r2 end;
      v_nombre := case when v_ronda = 4 then 'primera ronda' else 'ronda final' end;
      select * into m from public.course_modules where course_id = c.id and "order" = v_ronda;
      if m.id is null then
        insert into _0078_estado values ('SIN MÓDULO ' || v_ronda, c.name, 'La ruta no tiene módulo en esa posición.');
      elsif m.type = 'challenge' and m.challenge_data ? 'bank' then
        insert into _0078_estado values ('YA APLICADA', c.name, m.title || ' (' || v_nombre || ')');
      elsif m.type = 'lesson'
        and (m.content @> '[{"title":"Pendiente"}]'::jsonb or m.content::text like '%Banco de preguntas%') then
        update public.course_modules
           set type = 'challenge', challenge_type = 'quiz', challenge_data = v_cd,
               content = coalesce((
                 select jsonb_agg(e order by i)
                   from jsonb_array_elements(m.content) with ordinality as t(e, i)
                  where coalesce(e->>'title', '') <> 'Pendiente'
                    and coalesce(e->>'title', '') not like 'Banco de preguntas%'
               ), '[]'::jsonb),
               updated_at = now()
         where id = m.id;
        insert into _0078_estado values ('APLICADA', c.name,
          format('%s (%s): %s preguntas.', m.title, v_nombre, jsonb_array_length(v_cd->'questions')));
      else
        insert into _0078_estado values ('NO TOCADO', c.name,
          format('%s (%s): ya tiene contenido propio (%s). Cárgale preguntas desde el editor de ruta.', m.title, v_nombre, m.type));
      end if;
    end loop;
  end loop;
end $$;

select estado, curso, detalle from _0078_estado order by estado, curso;
